head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > ctrlShiftKey]<br/>Ctrl, Shift 키와 마우스 클릭을 복합적으로 사용하여 복수의 Cell 선택이 가능하게 설정합니다.",
    "validation" : [
        "ctrlShiftKey=true 로 설정 시 focusFooter=true 일때 Footer 영역에서 useCtrlKey, useShiftKey 속성이 true 로 동작합니다.",
        "Footer 영역에서 Ctrl 키를 누른 상태로 Cell 을 클릭하면 기존 선택 상태가 유지된 채 클릭된 Cell 이 선택됩니다.",
        "Footer 영역에서 Shift 키를 누른 상태로 Cell 을 클릭하면 마지막에 선택한 Cell 부터 클릭된 Cell 까지 직사각형 범위의 Cell 이 선택됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 이 _2 는 @spec3 (focusFooter=true 일때 Footer 영역 Ctrl/Shift 복합 선택) 검증용.
//  - ctrlShiftKey="true", focusFooter="true", useCtrlKey="true", useShiftKey="true", focusMode="cell" 고정 적용.
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="GridView ctrlShiftKey=true, focusFooter=true, useCtrlKey=true, useShiftKey=true, focusMode=cell / Footer Cell 클릭 → Ctrl+클릭(추가) → Shift+클릭(범위 추가) 후 [선택 범위 확인] 버튼으로 확인"', '', 'label1');

    // 범위 선택 확인용 dataList 생성 (col1~col4, 4행 Body)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 4);
    scwin.fillData();

    // target 생성 (Body 4컬럼 + Footer 2줄 그리드)
    await scwin.createGridView();
}



// Body 데이터 (4행)
scwin.fillData = function () {
    let rows = [
        { col1: "A1", col2: "B1", col3: "C1", col4: "D1" },
        { col1: "A2", col2: "B2", col3: "C2", col4: "D2" },
        { col1: "A3", col2: "B3", col3: "C3", col4: "D3" },
        { col1: "A4", col2: "B4", col3: "C4", col4: "D4" },
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성 (focusFooter=true, ctrlShiftKey=true, useCtrlKey/useShiftKey=true, focusMode=cell, Footer 2줄)
scwin.createGridView = async function () {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' checkAllType="false" id="" dataList="data:dlt_bind" focusMode="cell" focusFooter="true" ctrlShiftKey="true" useCtrlKey="true" useShiftKey="true" style="width:520px;height:340px;">';
    s += '<w2:caption style="" id="caption1" value="ctrlShiftKey Footer 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '<w2:footer style="" id="footer1">';
    s += '<w2:row style="" id="row3">';
    s += '<w2:column width="120" style="" inputType="text" id="ft1" value="합계1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="ft2" value="합계2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="ft3" value="합계3"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="ft4" value="합계4"></w2:column>';
    s += '</w2:row>';
    s += '<w2:row style="" id="row4">';
    s += '<w2:column width="120" style="" inputType="text" id="ft5" value="평균1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="ft6" value="평균2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="ft7" value="평균3"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="ft8" value="평균4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:footer>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 선택 범위 확인 :
//  - 사용자가 Footer Cell 을 클릭한 뒤 Ctrl+클릭(추가) / Shift+클릭(직사각형 범위 추가) 하여 범위를 선택한 상태에서 호출.
//  - getFocusedFooterCell() 로 포커스된 Footer Cell 의 상세 정보(id, rowIndex, colIndex)와 개수를 출력.
//  - getFocusedFooterIndex() 로 포커스된 Footer Cell 의 인덱스 목록을 병행 출력.
//  - 시각적으로 선택된 Footer Cell(.focusedTd) 개수도 병행 출력(내부 배열 부정확 가능성 대비).
scwin.btn_checkSelectedRange_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[옵션] focusFooter=" + target1.options.focusFooter
        + " / ctrlShiftKey=" + target1.options.ctrlShiftKey
        + " / useCtrlKey=" + target1.options.useCtrlKey
        + " / useShiftKey=" + target1.options.useShiftKey);

    let footerCells = target1.getFocusedFooterCell();
    let result = '';
    if (footerCells && footerCells.length > 0) {
        for (let i = 0; i < footerCells.length; i++) {
            result += '{id:"' + footerCells[i].id + '", rowIndex:' + footerCells[i].rowIndex + ', colIndex:' + footerCells[i].colIndex + '}';
            if (i < footerCells.length - 1) result += ', ';
        }
        result = '[' + result + ']';
    } else {
        result = '[]';
    }
    let cnt = footerCells ? footerCells.length : 0;
    bottom.setReturnValue("getFocusedFooterCell : " + result);
    bottom.setReturnValue("getFocusedFooterIndex : " + JSON.stringify(target1.getFocusedFooterIndex()));
    bottom.setReturnValue("포커스된 Footer Cell 개수 : " + cnt);

    // 시각적으로 선택된 Footer Cell(.focusedTd) 개수 (Footer 영역 한정 : {id}_foot_table)
    let footerArea = document.getElementById(target1.id + "_foot_table");
    let visualCnt = footerArea ? footerArea.querySelectorAll("td.focusedTd").length : 0;
    bottom.setReturnValue("시각 선택(.focusedTd) Footer Cell 개수 : " + visualCnt);
}
